def icono_svg(nombre, clases="size-5", stroke_width="1.8"):
    """
    Devuelve el markup <svg> de un icono registrado.
    `clases` permite ajustar tamaño/color con utilidades Tailwind
    ya compiladas (size-4, size-6, text-primary, etc.).
    """
    data = ICONOS.get(nombre, ICONOS["info"])
    paths = data if isinstance(data, list) else [data]
    inner = "".join(
        f'<path stroke-linecap="round" stroke-linejoin="round" d="{p}"/>'
        for p in paths
    )
    return (
        f'<svg class="{clases}" viewBox="0 0 24 24" fill="none" '
        f'stroke="currentColor" stroke-width="{stroke_width}" '
        f'aria-hidden="true">{inner}</svg>'
    )
